test("fetcher defaults to globalThis.fetch", async () => {
  const original = globalThis.fetch;
  let called = 0;
  globalThis.fetch = async () => { called++; return bytesResponse(Buffer.from("x")); };
  try {
    const b = await fetchResource({ skillId: "s", path: "p", bridgeBase: "http://x/skill" });
    assert.equal(b.toString("utf8"), "x");
    assert.equal(called, 1);
  } finally { globalThis.fetch = original; }
});
